import type { SourcedQuote } from './quoteTypes';

// Original bilingual science notes, not quotations by the named researchers.
// Each reference identifies a different passage or result in a freely readable source.
// Physics explanations do not imply that intention controls quantum outcomes.
type Passage = [reference: string, text: string, tr: string, ...tags: string[]];
const series = (
  start: number, source: string, sourceTr: string, sourceUrl: string,
  theme: string, passages: Passage[],
): SourcedQuote[] => passages.map(([reference, text, tr, ...tags], index) => ({
  id: `science-more-${String(start + index).padStart(3, '0')}`,
  text, tr, source, sourceTr: `${sourceTr} · ODA bilim uyarlaması`, sourceUrl,
  reference, tags: [theme, ...tags], category: 'science', kind: 'adaptation',
}));

